    log_abs_lfc = 2.7161288387,
    log_basemean = 0.6969544661,
    log_dispersion = -1.0392543813
  ),
  Astro_Shallow = c(
    intercept = -25.5607222667,
    log_donors = 1.6238444082,
    log_n_cells = 1.3592372995,
    log_reads_per_cell = 0.6460041875,
    log_abs_lfc = 2.8448768576,
